  ["WithTimeout returns a child that cancels itself. Always defer cancel() or you leak."] = "WithTimeout devuelve un hijo que se cancela solo. Siempre defer cancel() o habrá fugas.",
  ["Worker pool and pipeline"] = "Worker pool y pipeline",
  ["Worker pool: N goroutines range over a jobs channel; close(jobs) ends them; WaitGroup then close(results)."] = "Worker pool: N goroutines hacen range sobre un channel jobs; close(jobs) las termina; WaitGroup y luego close(results).",
  ["Workers are identical goroutines sharing one input channel. The channel is the queue."] = "Los workers son goroutines idénticas que comparten un channel de entrada. El channel es la cola.",
